#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 64
#define MAX_ROLES 4
#define MSG_PAYLOAD_SIZE 256

typedef enum { ROLE_GUEST = 0, ROLE_USER = 1, ROLE_ADMIN = 2, ROLE_SYSTEM = 3 } role_t;

typedef struct {
    char payload[MSG_PAYLOAD_SIZE];
    int priority;
    role_t sender_role;
    role_t required_role;
    int processed;
} message_t;

typedef struct {
    message_t *messages[MAX_QUEUE_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
} msg_queue_t;

typedef struct {
    role_t role;
    char name[64];
    int (*auth_validator)(role_t required, role_t actual);
} consumer_ctx_t;

static int default_auth_check(role_t required, role_t actual) {
    return actual >= required;
}

msg_queue_t *queue_create(void) {
    msg_queue_t *q = calloc(1, sizeof(msg_queue_t));
    if (!q) return NULL;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

int queue_enqueue(msg_queue_t *q, message_t *msg) {
    pthread_mutex_lock(&q->lock);
    if (q->count >= MAX_QUEUE_SIZE) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }
    q->messages[q->tail] = msg;
    q->tail = (q->tail + 1) % MAX_QUEUE_SIZE;
    q->count++;
    pthread_mutex_unlock(&q->lock);
    return 0;
}

/* Dequeue returns ownership of the message pointer to caller.
 * Returns NULL if queue is empty. */
message_t *queue_dequeue(msg_queue_t *q) {
    pthread_mutex_lock(&q->lock);
    if (q->count == 0) {
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    message_t *msg = q->messages[q->head];
    q->messages[q->head] = NULL;
    q->head = (q->head + 1) % MAX_QUEUE_SIZE;
    q->count--;
    pthread_mutex_unlock(&q->lock);
    return msg;
}

/* Peek at the front message without removing it.
 * The message remains in the queue. */
message_t *queue_peek(msg_queue_t *q) {
    pthread_mutex_lock(&q->lock);
    if (q->count == 0) {
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    message_t *msg = q->messages[q->head];
    pthread_mutex_unlock(&q->lock);
    return msg;
}

/* Process a batch of messages with role-based filtering.
 * Messages that don't pass auth are re-enqueued for later processing
 * by a higher-privileged consumer. */
int consume_filtered_batch(msg_queue_t *q, consumer_ctx_t *ctx, int batch_size) {
    int processed = 0;
    message_t *deferred[MAX_QUEUE_SIZE];
    int defer_count = 0;

    for (int i = 0; i < batch_size; i++) {
        /* Peek first to check authorization without consuming */
        message_t *peeked = queue_peek(q);
        if (peeked == NULL) {
            break;  /* Queue empty */
        }

        /* Check if consumer is authorized for this message */
        int authorized = ctx->auth_validator(peeked->required_role, ctx->role);

        if (authorized) {
            /* Now actually dequeue - but another thread may have consumed it */
            message_t *msg = queue_dequeue(q);
            if (msg == NULL) {
                continue;  /* Another thread consumed it between peek and dequeue */
            }
            /* Process the message - access payload */
            if (msg->priority > 0) {
                printf("[%s] Processing priority %d: %s\n",
                       ctx->name, msg->priority, msg->payload);
            } else {
                printf("[%s] Processing normal: %s\n",
                       ctx->name, msg->payload);
            }
            msg->processed = 1;
            free(msg);
            processed++;
        } else {
            /* Dequeue and defer for higher-privilege consumer */
            message_t *msg = queue_dequeue(q);
            if (msg != NULL) {
                deferred[defer_count++] = msg;
            }
        }
    }

    /* Re-enqueue deferred messages */
    for (int i = 0; i < defer_count; i++) {
        queue_enqueue(q, deferred[i]);
    }

    return processed;
}

consumer_ctx_t *create_consumer(const char *name, role_t role) {
    consumer_ctx_t *ctx = calloc(1, sizeof(consumer_ctx_t));
    if (!ctx) return NULL;
    strncpy(ctx->name, name, sizeof(ctx->name) - 1);
    ctx->role = role;
    ctx->auth_validator = default_auth_check;
    return ctx;
}

message_t *create_message(const char *payload, int priority,
                          role_t sender, role_t required) {
    message_t *msg = calloc(1, sizeof(message_t));
    if (!msg) return NULL;
    strncpy(msg->payload, payload, MSG_PAYLOAD_SIZE - 1);
    msg->priority = priority;
    msg->sender_role = sender;
    msg->required_role = required;
    msg->processed = 0;
    return msg;
}

int main(void) {
    msg_queue_t *q = queue_create();

    queue_enqueue(q, create_message("System health check", 5, ROLE_SYSTEM, ROLE_ADMIN));
    queue_enqueue(q, create_message("User notification", 1, ROLE_USER, ROLE_USER));
    queue_enqueue(q, create_message("Guest welcome", 0, ROLE_GUEST, ROLE_GUEST));

    consumer_ctx_t *admin = create_consumer("admin-worker", ROLE_ADMIN);
    consumer_ctx_t *user = create_consumer("user-worker", ROLE_USER);

    /* Simulate concurrent consumption */
    int result = consume_filtered_batch(q, user, 10);
    printf("User worker processed: %d\n", result);

    result = consume_filtered_batch(q, admin, 10);
    printf("Admin worker processed: %d\n", result);

    free(admin);
    free(user);
    free(q);
    return 0;
}
